resources.afterResponseScript:
insomnia.test('Status is 200', () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});
insomnia.test('Returns id and title', () => {
  const data = insomnia.response.json();
  insomnia.expect(data).to.have.property('id');
  insomnia.expect(data).to.have.property('title');
});

insomnia.test('Status is 201 (created)', () => {
  insomnia.expect(insomnia.response.code).to.eql(201);
});
insomnia.test('Returns the id of the new post', () => {
  insomnia.expect(insomnia.response.json()).to.have.property('id');
});

insomnia.test('Returns only the posts of user 1', () => {
  const posts = insomnia.response.json();
  insomnia.expect(posts).to.be.an('array').that.is.not.empty;
  insomnia.expect(posts.every((p) => p.userId === 1)).to.eql(true);
});
